package com.piratesgaming.unsolved; import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.entity.Player;import java.util.*;public class LivesCommand implements CommandExecutor,TabCompleter{final PiratesUnsolved p;public LivesCommand(PiratesUnsolved p){this.p=p;}public boolean onCommand(CommandSender s,Command c,String l,String[]a){if(!(s instanceof Player q))return true;p.ensurePlayerData(q);if(a.length==0){q.sendMessage(ChatColor.LIGHT_PURPLE+"Your lives: "+ChatColor.WHITE+p.lives(q));return true;}if(a[0].equalsIgnoreCase("withdraw")){int n=1;if(a.length>1)try{n=Integer.parseInt(a[1]);}catch(Exception ignored){}if(n<1||p.lives(q)<n){q.sendMessage(ChatColor.RED+"You don't have enough lives.");return true;}p.setLives(q,p.lives(q)-n);for(int i=0;i<n;i++)q.getInventory().addItem(p.lifeStar());q.sendMessage(ChatColor.GREEN+"You withdrew "+n+" life(s). Remaining lives: "+p.lives(q));return true;}return true;}public List<String> onTabComplete(CommandSender s,Command c,String l,String[]a){if(a.length==1)return List.of("withdraw");if(a.length==2&&a[0].equalsIgnoreCase("withdraw"))return List.of("1","2","3");return Collections.emptyList();}}
